s32 func_1517F9F4(s32 gfx, s32 ulx, s32 uly, s32 lrx, s32 lry, s32 arg5) {
    struct259 *vp;
    s32 temp;
    s32 clipped;
    s32 left;
    s32 top;
    s32 bottom;
    s32 right;
    Gfx *g;

    if (lrx < ulx) {
        temp = ulx;
        ulx = lrx;
        lrx = temp;
    }
    if (lry < uly) {
        temp = uly;
        uly = lry;
        lry = temp;
    }

    vp = &((struct259 *)D_800BE628)[arg5];
    temp = *(f32 *)((u8 *)vp + 0x2C);
    top = *(f32 *)((u8 *)vp + 0x24);
    right = *(f32 *)((u8 *)vp + 0x30);
    bottom = *(f32 *)((u8 *)vp + 0x28);

    if (!((uly < bottom) && (top < lry) && (ulx < right) && (temp < lrx))) {
        return gfx;
    }

    if (ulx < temp) {
        clipped = temp;
        goto clamp_x0_done;
    }
    if (right < ulx) {
        left = right;
        goto clamp_x0_else_done;
    }
    left = ulx;
clamp_x0_else_done:
    clipped = left;
clamp_x0_done:
    ulx = clipped;

    if (uly < top) {
        clipped = top;
        goto clamp_y0_done;
    }
    if (bottom < uly) {
        left = bottom;
        goto clamp_y0_else_done;
    }
    left = uly;
clamp_y0_else_done:
    clipped = left;
clamp_y0_done:
    uly = clipped;

    if (lrx < temp) {
        clipped = temp;
        goto clamp_x1_done;
    }
    if (right < lrx) {
        left = right;
        goto clamp_x1_else_done;
    }
    left = lrx;
clamp_x1_else_done:
    clipped = left;
clamp_x1_done:
    lrx = clipped;

    if (lry < top) {
        clipped = top;
        goto clamp_y1_done;
    }
    if (bottom < lry) {
        left = bottom;
        goto clamp_y1_else_done;
    }
    left = lry;
clamp_y1_else_done:
    clipped = left;
clamp_y1_done:
    lry = clipped;

    g = (Gfx *)gfx;
    gfx += 8;
    g->words.w0 = _SHIFTL(G_FILLRECT, 24, 8) | _SHIFTL(lrx, 14, 10) | _SHIFTL(lry, 2, 10);
    g->words.w1 = _SHIFTL(ulx, 14, 10) | _SHIFTL(uly, 2, 10);
    return gfx;
}
